declare namespace SigApi {
    interface DriveInfos {
        /**
         * Returns the letter of the drive
         * 
         * @returns {string} letter of the drive
         */
        getLetter(): string
        /**
         * Returns the error 
         * 
         * @returns {number} error
         */
        getError(): number
        /**
         * Returns the type of the drive
         * 
         * @returns {number} Bitmask: Bit0:[0=Drive does not exist, 1=Drive exists], Bit1:[0=Removable drive, 1=Hard Drive], Bit5..2:[0001=IDE, 0010=USB, 0011=CME221, 0100=Smartmedia, 0101=RAM Disk, 0110=SambaMount (only Salamander)]
         */
        getType(): number
        /**
         * Returns true, if the space info is available
         * 
         * @returns {boolean} true, if the space info is available
         */
        isSpaceInfoAvailable(): boolean
        /**
         * Returns the size of total space
         * 
         * @returns {number} size of total space
         */
        getTotalSpace(): number
        /**
         * Returns the size of free space
         * 
         * @returns {number} size of free space
         */
        getFreeSpace(): number
        /**
         * Returns the size of used space
         * 
         * @returns {number} size of used space
         */
        getUsedSpace(): number
        /**
         * Returns the type object of the drive
         * 
         * @returns {object} { {boolean} DriveExists, {boolean} HardDrive, {boolean} IDE, {boolean} USB, {boolean} CME221, {boolean} Smartmedia, {boolean} RAMDisk, {boolean} SambaMount }
         */
        getTypeObject(): {
            DriveExists: boolean,
            HardDrive: boolean,
            IDE: boolean,
            USB: boolean,
            CME221: boolean,
            Smartmedia: boolean,
            RAMDisk: boolean,
            SambaMount: boolean
        }
    }
}
